<!DOCTYPE html>
<html lang="en">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Mail</title>
    <style>
        * {
            margin: 0px;
            padding: 0px;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
        }

        p {
            margin: 1rem 0;
        }

        .social-media table th {
            padding: 0px 7px;
        }

        .title_icon {
            position: relative;
            padding: 0 10px;
            margin: 0 auto;
            display: table;
            line-height: normal;
        }

        .title_icon::before {
            content: "";
            background-color: #fff;
            position: absolute;
            width: 200px;
            height: 1px;
            display: block;
            top: 50%;
            left: -200px;
        }

        .title_icon::after {
            content: "";
            background-color: #fff;
            position: absolute;
            width: 200px;
            height: 1px;
            display: block;
            top: 50%;
            right: -200px;
        }

        .header {
            padding: 10px;
            background: linear-gradient(to right, #BDCAC5, #E2EBE7);
            border-radius: 0px 0px 15px 15px;
            margin: 0px 50px;
        }
    </style>
</head>

<body>
    <section style="max-width: 800px; height: auto; margin: 0px auto;">
        <header class="header">
            <div class="header-img" style="width: 100%; text-align: center; padding: 40px 0px; border: 1px solid #556945; border-radius: 15px">
                <img src="{{ asset('front/images/Mail-logo.png') }}" alt="logo">
            </div>
        </header>
        <div class="container" style="text-align: center; margin: 0px 50px;">
            <h2 style="margin: 20px 0px;">Forgot Password</h2>
            <div class="content" style="text-align: start; padding:20px; border: 1px solid black; border-radius: 15px">
                <p style="font-weight: 700;">Subject: Forgot Password</p>
                <p style="font-weight: 700;">Dear  {{!empty($user->name)?$user->name:''}},</p>
               
                <p>Here are your account details :</p>
                <p>Password : <b>{{!empty($user->password)?$user->password:''}}</b></p>
                <p style="color: #556945;">Please keep this information secure and do not share it with anyone</p>
            </div>
            <p>For more Information</p>
            <a href="{{url('/')}}" style="background-color: #556945; color:#fff; border-radius:15px; border:none; margin-bottom: 30px; padding:10px 20px; text-decoration: none; display: inline-block;">Visit Now</a>
        </div>
        <footer class="footer" style="background-color: #556945; color: #fff; padding:20px 50px; text-align:center;">
